package com.collectiq.security;
import org.springframework.context.annotation.*;import org.springframework.security.config.Customizer;import org.springframework.security.config.annotation.web.builders.HttpSecurity;import org.springframework.security.config.http.SessionCreationPolicy;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationConverter;import org.springframework.security.web.SecurityFilterChain;
@Configuration public class SecurityConfig{
 @Bean SecurityFilterChain security(HttpSecurity http)throws Exception{return http.csrf(c->c.disable()).cors(Customizer.withDefaults()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/actuator/health","/api/auth/**").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(Customizer.withDefaults())).build();}
 @Bean JwtDecoder jwtDecoder(@org.springframework.beans.factory.annotation.Value("${JWT_ISSUER_URI:https://accounts.google.com}")String issuer,@org.springframework.beans.factory.annotation.Value("${JWT_JWK_SET_URI:https://www.googleapis.com/oauth2/v3/certs}")String jwks){return NimbusJwtDecoder.withJwkSetUri(jwks).build();}
}